// frames.ts — from the ICRF to the true equator and ecliptic of date.
//
// IAU 2006 precession (Fukushima-Williams angles, frame bias included) and IAU
// 2000B's nutation terms, composed as in ERFA's fw2m. The constants are
// generated by tools/build_frames.py and checked there against ERFA; nothing
// is typed here.
//
// The nutation arguments are the full IERS 2003 polynomials, not the linear
// ones 2000B is published with: those serve 1995–2050, and by the ends of the
// tables' span (1550, 2650) they had drifted far enough to put every place
// 14 mas out. With the full arguments the worst is 2.6 mas.
//
// BEYOND THE DE440 TABLES (before 1550, after 2650 — the DE441 tables) IAU
// 2006 is no longer the right model: it is a polynomial fitted to a few
// centuries and is 47 arcminutes out by 13,000 BC. There the precession is
// Vondrák, Capitaine & Wallace's long-term model (valid ±200,000 years),
// built from its ecliptic and equator poles as ERFA's ltpb does, with the same
// nutation on top. The two models already differ by 10–15 mas at the tables'
// ends, so across BLEND_YEARS outside them the frame turns smoothly from one
// to the other instead of stepping. Inside the DE440 tables nothing changes.

import {
  FW_GAMB, FW_PHIB, FW_PSIB, OBL06, DELAUNAY, NUT_OFFSET_PSI, NUT_OFFSET_EPS, NUT_TERMS,
} from "./generated/frames.ts";
import {
  SPAN_START, SPAN_END, BLEND_YEARS, LTP_ECL_POLY, LTP_ECL_PER, LTP_EQU_POLY, LTP_EQU_PER, LTP_EPS0, LTP_BIAS,
  EO_FROM_EPOCH, EO_STEP_YEARS, EO_MEAN,
} from "./generated/frames-long.ts";

export type Mat3 = [number, number, number, number, number, number, number, number, number];

const AS2R = Math.PI / 648000;
const TURNAS = 1296000;
const J2000 = 2451545.0;
const U_AS_TENTH = 1e-7 * AS2R; // 0.1 microarcsecond in radians

function poly(c: readonly number[], t: number): number {
  let v = 0;
  for (let i = c.length - 1; i >= 0; i--) v = v * t + c[i];
  return v;
}

/** Julian centuries of TT from J2000. */
export const centuries = (jdTT: number) => (jdTT - J2000) / 36525;

/** Mean obliquity of the ecliptic, IAU 2006, radians. */
export function meanObliquity(jdTT: number): number {
  return poly(OBL06, centuries(jdTT)) * AS2R;
}

/**
 * The fundamental arguments l, l′, F, D and Ω (the Moon's mean node), radians,
 * at t Julian centuries of TT from J2000.
 */
export function delaunay(t: number): number[] {
  return DELAUNAY.map((c) => (poly(c, t) % TURNAS) * AS2R);
}

/** Nutation in longitude and obliquity, IAU 2000B's terms, radians. */
export function nutation(jdTT: number): { dpsi: number; deps: number } {
  const t = centuries(jdTT);
  const fa = delaunay(t);
  let dpsi = 0, deps = 0;
  for (let i = 0; i < NUT_TERMS.length; i += 11) {
    const arg = NUT_TERMS[i] * fa[0] + NUT_TERMS[i + 1] * fa[1] + NUT_TERMS[i + 2] * fa[2]
      + NUT_TERMS[i + 3] * fa[3] + NUT_TERMS[i + 4] * fa[4];
    const s = Math.sin(arg), c = Math.cos(arg);
    dpsi += (NUT_TERMS[i + 5] + NUT_TERMS[i + 6] * t) * s + NUT_TERMS[i + 7] * c;
    deps += (NUT_TERMS[i + 8] + NUT_TERMS[i + 9] * t) * c + NUT_TERMS[i + 10] * s;
  }
  return { dpsi: (dpsi + NUT_OFFSET_PSI) * U_AS_TENTH, deps: (deps + NUT_OFFSET_EPS) * U_AS_TENTH };
}

// ERFA's rotation convention: R ← Rx(φ)·R, Rx(φ) = [[1,0,0],[0,c,s],[0,−s,c]].
function rx(phi: number, r: Mat3): Mat3 {
  const s = Math.sin(phi), c = Math.cos(phi);
  return [
    r[0], r[1], r[2],
    c * r[3] + s * r[6], c * r[4] + s * r[7], c * r[5] + s * r[8],
    -s * r[3] + c * r[6], -s * r[4] + c * r[7], -s * r[5] + c * r[8],
  ];
}
function rz(psi: number, r: Mat3): Mat3 {
  const s = Math.sin(psi), c = Math.cos(psi);
  return [
    c * r[0] + s * r[3], c * r[1] + s * r[4], c * r[2] + s * r[5],
    -s * r[0] + c * r[3], -s * r[1] + c * r[4], -s * r[2] + c * r[5],
    r[6], r[7], r[8],
  ];
}

export interface Frame {
  /** Bias-precession-nutation: ICRF → true equator and equinox of date. */
  npb: Mat3;
  /** True obliquity of date, radians. */
  eps: number;
  dpsi: number;
  deps: number;
  epsA: number;
}

/**
 * How much of IAU 2006 a moment takes: 1 inside the DE440 tables, falling to
 * 0 across BLEND_YEARS outside them, 0 beyond — where the long-term model
 * takes over entirely.
 */
export function iauWeight(jdTT: number): number {
  const outside = jdTT < SPAN_START ? SPAN_START - jdTT : jdTT > SPAN_END ? jdTT - SPAN_END : 0;
  return Math.max(0, 1 - outside / (BLEND_YEARS * 365.25));
}

/** The frame of date at a TT Julian Day. */
export function frameOfDate(jdTT: number): Frame {
  const w = iauWeight(jdTT);
  if (w === 1) return frameIAU2006(jdTT);
  const long = frameLongTerm(jdTT);
  if (w === 0) return long;
  // Blend: the long-term frame is the IAU one turned by a small rotation
  // (about 10⁻⁷ rad); take the share (1 − w) of that rotation.
  const iau = frameIAU2006(jdTT);
  const d = mul(long.npb, transpose(iau.npb));
  const u = 1 - w;
  const ax = u * (d[5] - d[7]) / 2, ay = u * (d[6] - d[2]) / 2, az = u * (d[1] - d[3]) / 2;
  const turn: Mat3 = [1, az, -ay, -az, 1, ax, ay, -ax, 1];
  const epsA = w * iau.epsA + u * long.epsA;
  return { npb: mul(turn, iau.npb), eps: epsA + iau.deps, dpsi: iau.dpsi, deps: iau.deps, epsA };
}

function mul(a: Mat3, b: Mat3): Mat3 {
  const r = [0, 0, 0, 0, 0, 0, 0, 0, 0] as Mat3;
  for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) {
    r[3 * i + j] = a[3 * i] * b[j] + a[3 * i + 1] * b[3 + j] + a[3 * i + 2] * b[6 + j];
  }
  return r;
}
const transpose = (m: Mat3): Mat3 => [m[0], m[3], m[6], m[1], m[4], m[7], m[2], m[5], m[8]];

/** One long-term pole series at t centuries from J2000: the two coordinates, radians. */
function ltpPole(poly: readonly (readonly number[])[], per: readonly (readonly number[])[], t: number): [number, number] {
  let a = 0, b = 0;
  const w = 2 * Math.PI * t;
  for (const [period, ca, cb, sa, sb] of per) {
    const s = Math.sin(w / period), c = Math.cos(w / period);
    a += c * ca + s * sa;
    b += c * cb + s * sb;
  }
  let tk = 1;
  for (let k = 0; k < 4; k++) {
    a += poly[0][k] * tk;
    b += poly[1][k] * tk;
    tk *= t;
  }
  return [a * AS2R, b * AS2R];
}

/**
 * Long-term bias-precession (ICRS → mean equator and equinox of date) and the
 * mean obliquity of date, the angle between the two poles. As ERFA's ltpb.
 */
export function longTermPrecession(jdTT: number): { pb: Mat3; epsA: number } {
  const t = (jdTT - J2000) / 36525;
  const [p, q] = ltpPole(LTP_ECL_POLY, LTP_ECL_PER, t);
  const w = Math.sqrt(Math.max(0, 1 - p * p - q * q));
  const s0 = Math.sin(LTP_EPS0 * AS2R), c0 = Math.cos(LTP_EPS0 * AS2R);
  const pecl = [p, -q * c0 - w * s0, -q * s0 + w * c0];
  const [x, y] = ltpPole(LTP_EQU_POLY, LTP_EQU_PER, t);
  const peq = [x, y, Math.sqrt(Math.max(0, 1 - x * x - y * y))];
  // The equinox: along the line where the two planes cross.
  let ex = peq[1] * pecl[2] - peq[2] * pecl[1], ey = peq[2] * pecl[0] - peq[0] * pecl[2], ez = peq[0] * pecl[1] - peq[1] * pecl[0];
  const n = Math.hypot(ex, ey, ez);
  ex /= n; ey /= n; ez /= n;
  const mid = [peq[1] * ez - peq[2] * ey, peq[2] * ex - peq[0] * ez, peq[0] * ey - peq[1] * ex];
  const rows = [[ex, ey, ez], mid, peq];
  const [dx, de, dr] = LTP_BIAS.map((v) => v * AS2R);
  const pb = rows.flatMap((r) => [r[0] - r[1] * dr + r[2] * dx, r[0] * dr + r[1] + r[2] * de, -r[0] * dx - r[1] * de + r[2]]) as Mat3;
  const cosEps = peq[0] * pecl[0] + peq[1] * pecl[1] + peq[2] * pecl[2];
  return { pb, epsA: Math.acos(Math.min(1, cosEps)) };
}

function frameLongTerm(jdTT: number): Frame {
  const { pb, epsA } = longTermPrecession(jdTT);
  const { dpsi, deps } = nutation(jdTT);
  // Nutation as ERFA's numat: N = Rx(−(εA + Δε)) · Rz(−Δψ) · Rx(εA).
  let n: Mat3 = [1, 0, 0, 0, 1, 0, 0, 0, 1];
  n = rx(epsA, n);
  n = rz(-dpsi, n);
  n = rx(-(epsA + deps), n);
  return { npb: mul(n, pb), eps: epsA + deps, dpsi, deps, epsA };
}

/**
 * The mean equation of the origins (radians) from the long-term model, for
 * sidereal time beyond the DE440 tables: GMST = ERA − EO. Cubic Hermite through
 * the generated table (tools/build_frames.py integrates it).
 */
export function meanEquationOfOrigins(jdTT: number): number {
  const epoch = 2000 + (jdTT - J2000) / 365.25;
  const last = EO_MEAN.length - 1;
  const x = (epoch - EO_FROM_EPOCH) / EO_STEP_YEARS;
  let i = Math.floor(x);
  if (i < 1) i = 1;
  else if (i > last - 2) i = last - 2;
  const u = x - i;
  const p0 = EO_MEAN[i - 1], p1 = EO_MEAN[i], p2 = EO_MEAN[i + 1], p3 = EO_MEAN[i + 2];
  const m1 = (p2 - p0) / 2, m2 = (p3 - p1) / 2;
  const u2 = u * u, u3 = u2 * u;
  return ((2 * u3 - 3 * u2 + 1) * p1 + (u3 - 2 * u2 + u) * m1 + (-2 * u3 + 3 * u2) * p2 + (u3 - u2) * m2) * AS2R;
}

/** The frame of date by IAU 2006 / 2000B: every moment inside the DE440 tables. */
function frameIAU2006(jdTT: number): Frame {
  const t = centuries(jdTT);
  const gamb = poly(FW_GAMB, t) * AS2R;
  const phib = poly(FW_PHIB, t) * AS2R;
  const psib = poly(FW_PSIB, t) * AS2R;
  const epsA = poly(OBL06, t) * AS2R;
  const { dpsi, deps } = nutation(jdTT);
  // fw2m: R = Rx(−ε)·Rz(−ψ)·Rx(φ̄)·Rz(γ̄), with ψ and ε the nutated angles.
  let r: Mat3 = [1, 0, 0, 0, 1, 0, 0, 0, 1];
  r = rz(gamb, r);
  r = rx(phib, r);
  r = rz(-(psib + dpsi), r);
  r = rx(-(epsA + deps), r);
  return { npb: r, eps: epsA + deps, dpsi, deps, epsA };
}

export function apply(m: Mat3, v: number[]): [number, number, number] {
  return [
    m[0] * v[0] + m[1] * v[1] + m[2] * v[2],
    m[3] * v[0] + m[4] * v[1] + m[5] * v[2],
    m[6] * v[0] + m[7] * v[1] + m[8] * v[2],
  ];
}

/** Equatorial (true equator of date) → ecliptic (true ecliptic of date). */
export function toEcliptic(v: number[], eps: number): [number, number, number] {
  const s = Math.sin(eps), c = Math.cos(eps);
  return [v[0], c * v[1] + s * v[2], -s * v[1] + c * v[2]];
}
